#!/bin/sh
# Install Direwolf for RigBroker. Run ON THE PI:   sudo sh deploy/install-direwolf.sh
# - installs the Debian direwolf package (and alsa-utils for `aplay -l`)
# - installs the direwolf@.service template (configs are generated by RigBroker)
# - makes sure the distro's own direwolf service can't grab the sound card
# Safe to re-run.
set -eu
[ "$(id -u)" -eq 0 ] || { echo "run with sudo"; exit 1; }
cd "$(dirname "$0")"

apt-get update -qq
DEBIAN_FRONTEND=noninteractive apt-get install -y -qq direwolf alsa-utils

install -m 0644 'direwolf@.service' /etc/systemd/system/direwolf@.service
systemctl daemon-reload
# the Debian package may ship a plain direwolf.service: keep it off so only RigBroker
# decides when Direwolf runs (it owns the Digirig's audio)
systemctl disable --now direwolf.service 2>/dev/null || true

usermod -aG audio,dialout ham
echo
dpkg-query -W -f='Direwolf ${Version} installed\n' direwolf
echo "direwolf@.service installed (not enabled - RigBroker starts it)."
echo "Configs: /home/ham/.local/state/rigbroker/direwolf/{aprs,aprs-rx,pkt}.conf"
echo "USB sound cards:"; aplay -l 2>/dev/null | grep -i usb || echo "  none yet (plug in the Digirig)"
